import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0
    if k >= len(jobs):
        return sum(job[2] for job in jobs)

    coords = sorted({x for s, e, _ in jobs for x in (s, e)})
    idx = {x: i for i, x in enumerate(coords)}
    m = len(coords)

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        fwd_idx = len(adj[u])
        rev_idx = len(adj[v])
        adj[u].append([v, cap, cost, rev_idx])
        adj[v].append([u, 0, -cost, fwd_idx])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(idx[start], idx[end], 1, -pay)

    INF = 10**18
    pot = [INF] * m
    pot[0] = 0
    for u in range(m - 1):
        pu = pot[u]
        for v, cap, cost, _ in adj[u]:
            if cap > 0:
                nd = pu + cost
                if nd < pot[v]:
                    pot[v] = nd

    total_cost = 0
    for _ in range(k):
        dist = [INF] * m
        dist[0] = 0
        parent_v = [-1] * m
        parent_e = [-1] * m
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            pu = pot[u]
            for ei, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + pu - pot[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_v[v] = u
                        parent_e[v] = ei
                        heapq.heappush(pq, (nd, v))

        for v in range(m):
            pot[v] += dist[v]

        if pot[m - 1] >= 0:
            break

        total_cost += pot[m - 1]
        v = m - 1
        while v != 0:
            u = parent_v[v]
            ei = parent_e[v]
            edge = adj[u][ei]
            edge[1] -= 1
            adj[v][edge[3]][1] += 1
            v = u

    return -total_cost
